)

if (!refactor) {
  log(`[${taskId}] REFACTOR FAILED: agent returned null`)
  return null
}
if (!refactor.success && refactor.failure_reason && !refactor.failure_reason.toLowerCase().includes('nothing to')) {
  log(`[${taskId}] REFACTOR FAILED: ${refactor.failure_reason}`)
