"""wave_builder.py — BFS wave grouping for parallel lane dispatch.

Given a lane plan with dependency edges, groups tasks into waves using
Kahn's algorithm.  Tasks within a wave have no mutual dependencies and
can run concurrently.  Wave N's tasks depend only on tasks in waves < N.
"""

from __future__ import annotations

from collections.abc import Iterator
from dataclasses import dataclass


class CyclicDependencyError(ValueError):
    """Raised when build_waves detects a cycle in the dependency graph."""


class MissingDependencyError(ValueError):
    """Raised when a lane references a dependency that does not exist in lanes."""


@dataclass
class WaveStats:
    """Statistics derived from a wave plan."""

    total_tasks: int
    num_waves: int
    max_parallelism: int
    critical_path_length: int


class WaveResult:
    """Return type for build_waves — wraps the wave list with metadata.

    Supports iteration and indexing so existing callers using
    ``build_waves()[0]`` or ``for wave in build_waves()`` continue to work.
    """

    def __init__(self, waves: list[list[str]]) -> None:
        self.waves = waves
        self.stats = WaveStats(
            total_tasks=sum(len(w) for w in waves),
            num_waves=len(waves),
            max_parallelism=max((len(w) for w in waves), default=0),
            critical_path_length=len(waves),
        )

    # --- list-like protocol ---------------------------------------------------

    def __iter__(self) -> Iterator[list[str]]:
        return iter(self.waves)

    def __getitem__(self, index: int) -> list[str]:
        return self.waves[index]

    def __len__(self) -> int:
        return len(self.waves)

    @property
    def summary(self) -> str:
        """One-line human summary of the wave plan.

        Returns ``'N tasks in W waves (max parallelism: P, critical path: C)'``
        for non-empty graphs, or ``'0 tasks in 0 waves'`` for an empty graph.
        """
        s = self.stats
        if s.total_tasks == 0:
            return "0 tasks in 0 waves"
        return (
            f"{s.total_tasks} tasks in {s.num_waves} waves"
            f" (max parallelism: {s.max_parallelism}, critical path: {s.critical_path_length})"
        )

    def __repr__(self) -> str:  # pragma: no cover
        return f"WaveResult(waves={self.waves!r}, stats={self.stats!r})"


def build_waves(
    lanes: dict[str, dict],
    depends_on_key: str = "depends_on",
) -> WaveResult:
    """Return BFS-layered waves from a lane dependency graph.

    Parameters
    ----------
    lanes:
        Mapping of lane_id -> lane dict.  Each lane dict may contain a
        ``depends_on`` list of upstream lane IDs.
    depends_on_key:
        Key name for the dependency list within each lane dict.

    Returns
    -------
    WaveResult wrapping the list of waves plus a WaveStats summary.
    """
    ids = list(lanes.keys())
    id_set = set(ids)

    # Validate all dependency references before running BFS.
    for lane_id in ids:
        deps = lanes[lane_id].get(depends_on_key) or []
        for dep in deps:
            if dep not in id_set:
                raise MissingDependencyError(
                    f"Lane '{lane_id}' depends on '{dep}', which does not exist in lanes."
                )

    in_deg: dict[str, int] = {}
    adj: dict[str, list[str]] = {}

    for lane_id in ids:
        deps = lanes[lane_id].get(depends_on_key) or []
        in_deg[lane_id] = len(deps)
        for dep in deps:
            adj.setdefault(dep, []).append(lane_id)

    waves: list[list[str]] = []
    queue = sorted(lid for lid in ids if in_deg[lid] == 0)

    while queue:
        waves.append(list(queue))
        next_queue: list[str] = []
        for lid in queue:
            for child in adj.get(lid, []):
                in_deg[child] -= 1
                if in_deg[child] == 0:
                    next_queue.append(child)
        queue = sorted(next_queue)

    cycle_nodes = sorted(lid for lid in ids if in_deg[lid] > 0)
    if cycle_nodes:
        raise CyclicDependencyError(
            f"Cycle detected among tasks: {', '.join(cycle_nodes)}"
        )

    return WaveResult(waves)

# RED tests for task-001: validate_lane_plan — structural validation before build_waves
# Traceability: AC1-AC4 → tests/test_wave_builder.py

import pytest


class TestTask_001_AC4:
    def test_ac4_ac4_validatelaneplan_is_importable_from_datumwavebuilder(self):
        """
        AC4: validate_lane_plan is importable from datum.wave_builder
        """
        # Act — will raise ImportError if the symbol does not exist
        from datum.wave_builder import validate_lane_plan

        # Assert — function must be callable
        assert callable(validate_lane_plan)


class TestTask_001_AC1:
    """AC1: validate_lane_plan raises ValueError if a lane is missing 'id' or 'files' keys."""

    def test_ac1_missing_id_key_raises_value_error(self):
        """Lane dict without 'id' key must raise ValueError."""
        from datum.wave_builder import validate_lane_plan

        plan = {
            "lanes": [{"files": ["a.py"]}],  # no 'id'
            "topological_order": [],
        }
        with pytest.raises(ValueError):
            validate_lane_plan(plan)

    def test_ac1_missing_files_key_raises_value_error(self):
        """Lane dict without 'files' key must raise ValueError."""
        from datum.wave_builder import validate_lane_plan

        plan = {
            "lanes": [{"id": "lane-1"}],  # no 'files'
            "topological_order": ["lane-1"],
        }
        with pytest.raises(ValueError):
            validate_lane_plan(plan)

    def test_ac1_missing_both_id_and_files_raises_value_error(self):
        """Lane dict with neither 'id' nor 'files' must raise ValueError."""
        from datum.wave_builder import validate_lane_plan

        plan = {
            "lanes": [{"depends_on": []}],
            "topological_order": [],
        }
        with pytest.raises(ValueError):
            validate_lane_plan(plan)


class TestTask_001_AC2:
    """AC2: validate_lane_plan raises ValueError if topological_order contains IDs not in lanes."""

    def test_ac2_orphan_topo_id_raises_value_error(self):
        """topological_order referencing an ID absent from lanes must raise ValueError."""
        from datum.wave_builder import validate_lane_plan

        plan = {
            "lanes": [{"id": "lane-1", "files": ["a.py"]}],
            "topological_order": ["lane-1", "lane-ghost"],  # 'lane-ghost' not in lanes
        }
        with pytest.raises(ValueError):
            validate_lane_plan(plan)

    def test_ac2_entirely_unknown_topo_ids_raise_value_error(self):
        """topological_order with no matching lane IDs must raise ValueError."""
        from datum.wave_builder import validate_lane_plan

        plan = {
            "lanes": [{"id": "lane-A", "files": ["x.py"]}],
            "topological_order": ["lane-X", "lane-Y"],  # neither exists in lanes
        }
        with pytest.raises(ValueError):
            validate_lane_plan(plan)


class TestTask_001_AC3:
    """AC3: validate_lane_plan returns None silently for a valid plan."""

    def test_ac3_valid_plan_returns_none(self):
        """A structurally valid plan must return None with no exception."""
        from datum.wave_builder import validate_lane_plan

        plan = {
            "lanes": [
                {"id": "lane-1", "files": ["a.py"]},
                {"id": "lane-2", "files": ["b.py"]},
            ],
            "topological_order": ["lane-1", "lane-2"],
        }
        result = validate_lane_plan(plan)
        assert result is None

    def test_ac3_valid_plan_with_empty_topological_order_returns_none(self):
        """A valid plan where topological_order is empty must return None."""
        from datum.wave_builder import validate_lane_plan

        plan = {
            "lanes": [{"id": "lane-1", "files": ["a.py"]}],
            "topological_order": [],
        }
        result = validate_lane_plan(plan)
        assert result is None

    def test_ac3_valid_plan_with_no_lanes_returns_none(self):
        """An empty lanes list with empty topological_order is a valid (trivial) plan."""
        from datum.wave_builder import validate_lane_plan

        plan = {
            "lanes": [],
            "topological_order": [],
        }
        result = validate_lane_plan(plan)
        assert result is None

